WITH flattened_attrs AS (SELECT id, currency, tier_limits, tier_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers WHERE currency IN ('THB', 'EUR')) SELECT currency, CASE WHEN lowest_price >= 34 THEN 'PREMIUM' ELSE 'STANDARD' END AS lowest_price_tier, SUM(avg_tier_price) AS total_avg_tier_price, APPROX_PERCENTILE(avg_tier_price, ARRAY(0.25, 0.5, 0.75)) AS avg_tier_price_quartiles, ROUND(AVG(avg_tier_price), 2) AS avg_avg_tier_price, AVG(lowest_price) AS avg_lowest_price, COUNT(CASE WHEN currency = 'THB' THEN 1 END) AS thb_count FROM flattened_attrs GROUP BY GROUPING SETS ((currency, CASE WHEN lowest_price >= 34 THEN 'PREMIUM' ELSE 'STANDARD' END), (currency), ()) ORDER BY avg_lowest_price;
